groups.unshift(['Newsletter',[['Latest posts','newsletter.html']]]);
groups.splice(1,0,['Community',[['Raid videos','raid-videos.html'],['Mastery planner','mastery-planner.html'],['Contacts','contacts.html']]]);
groups.unshift(['Welcome',[['Home','home.html']]]);
const nav=document.createElement('aside');nav.id='site-sidebar';nav.setAttribute('aria-label','Website navigation');nav.innerHTML='<a class="site-brand" href="home.html"><img class="atlas-logo" src="logo.svg" width="28" height="28" alt=""><strong>GUARDIAN ATLAS</strong></a><button id="site-nav-close" aria-label="Close navigation">×</button>'+groups.map(([title,links])=>'<nav aria-label="'+title+'"><h2>'+title+'</h2>'+links.map(([label,href])=>'<a href="'+href+'">'+label+'</a>').join('')+'</nav>').join('');document.body.prepend(nav);document.body.classList.add('shared-layout');const issueScript=document.createElement('script');issueScript.src=new URL('issue-report.js',icon.href).href;document.head.append(issueScript);
const toggle=document.createElement('button');toggle.id='site-nav-toggle';toggle.textContent='☰ All sections';toggle.setAttribute('aria-controls','site-sidebar');toggle.setAttribute('aria-expanded','false');document.body.prepend(toggle);
const version=document.createElement('a');version.className='site-version';version.href='newsletter-v355.html';version.textContent='Game data 3.55.0 · update notes';nav.querySelector('.site-brand').after(version);
const currentPage=location.pathname.split('/').pop();if(['research.html','raid.html','source-validation.html','files.html'].includes(currentPage)){const note=document.createElement('p');note.className='snapshot-note';note.textContent=currentPage==='files.html'?'Current data: 3.55.0. Changed files have direct downloads. Release archives retain their labeled 3.54.0 contents.':'Tables and Lua sources: 3.55.0. Native code, assembly, damage validation and historical behavior reports: 3.54.0, not revalidated for this patch.';document.querySelector('main')?.prepend(note);}
